SELECT ts.interval_code, COUNT(*) n, MAX(ts.generated_at) last_generated_at, TIMESTAMPDIFF(MINUTE, MAX(ts.generated_at), NOW()) stale_vs_session_now_min FROM trade_signal ts INNER JOIN (SELECT symbol, MAX(generated_at) mx FROM trade_signal WHERE interval_code IN ('1m','5m','1h') GROUP BY symbol, interval_code) x ON x.symbol=ts.symbol AND x.mx=ts.generated_at AND ts.interval_code IN ('1m','5m','1h') GROUP BY ts.interval_code ORDER BY ts.interval_code